@Override public TraceHook traceRead(long begin,long end,TraceReadListener listener){
  TraceMemoryHook hook=new TraceMemoryHook(true);
  if (listener != null) {
    hook.traceReadListener=listener;
  }
  try {
    backend.hook_add_new((ReadHook)hook,begin,end,this);
  } catch (NullPointerException | IllegalArgumentException e) {
    e.printStackTrace();
  }
  return hook;
}
